sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float phase;
uniform float angle;
uniform float spacing;
uniform float magnitude;
uniform float warpAngle;
uniform float speed;
uniform float screenSpace;
uniform float crossSpacing;
uniform float crossMagnitude;
uniform float origin;
uniform float style;
uniform float damping;
uniform float dampingSpace;
uniform float dampingOrigin;

half4 main(float2 coord) {
    float a = radians(angle);
    float b = radians(warpAngle);
    float2 da = float2(cos(a), sin(a));
    float2 db = float2(cos(b), sin(b));
    bool corner = origin > 0.5;
    float2 at = corner ? (coord - float2(screen.x, screen.y + screen.w)) / max(min(screen.z, screen.w), 1.0) : coord / max(screenSpace > 0.5 ? screen.zw : size, float2(1.0));
    float shift = corner ? phase : 0.0;
    float t = (corner ? 0.0 : 6.2831853 * phase) + time * speed;
    float unit = min(screen.z, screen.w) * 0.01;
    float along = dot(at, da);
    float off = abs(along - dampingOrigin);
    float stretch = dampingSpace >= 0.0 ? mix(1.0, off, dampingSpace) : mix(1.0, 1.0 - off, -dampingSpace);
    float k1 = style > 0.5 ? (spacing > 0.0 ? 1080.0 / spacing : 0.0) : spacing;
    float k2 = style > 0.5 ? (crossSpacing > 0.0 ? 1080.0 / crossSpacing : 0.0) : crossSpacing;
    float2 move = magnitude * unit * mix(1.0, off, damping) * sin(k1 * (along * stretch + shift) + t) * db;
    move += crossMagnitude * unit * sin(k2 * (dot(at, db) + shift) + t) * da;
    float2 p = coord + move;
    return image.eval(style > 0.5 ? clamp(p, screen.xy + 0.5, screen.xy + screen.zw - 0.5) : p);
}
